style:
/* 显式选择的列表样式接管模板默认圆点装饰，避免 data-list 被模板 ul/li 规则盖掉。 */
.tw-jianya.resume-paper .paper-rich ul[data-list],
.tw-jianya.resume-paper .paper-rich ol[data-list] {
  margin: 0.5mm 0 0;
  padding-left: 1.2em;
}
.tw-jianya.resume-paper .paper-rich ul[data-list] > li,
.tw-jianya.resume-paper .paper-rich ol[data-list] > li {
  padding-left: 0;
  position: relative;
}
.tw-jianya.resume-paper .paper-rich ul[data-list] > li::before,
.tw-jianya.resume-paper .paper-rich ol[data-list] > li::before {
  content: none;
  width: auto;
  height: auto;
  border-radius: 0;
  background: none;
  border: 0;
  box-shadow: none;
  left: auto;
  right: auto;
  top: auto;
  margin: 0;
  padding: 0;
}
.tw-jianya.resume-paper .paper-rich ul[data-list="disc"] { list-style-type: disc; }
.tw-jianya.resume-paper .paper-rich ul[data-list="circle"] { list-style-type: circle; }
.tw-jianya.resume-paper .paper-rich ul[data-list="square"] { list-style-type: square; }
.tw-jianya.resume-paper .paper-rich ul[data-list="square-open"] { list-style-type: "□   "; }
.tw-jianya.resume-paper .paper-rich ul[data-list="square-open"] > li::marker { font-size: 0.62em; }
.tw-jianya.resume-paper .paper-rich ul[data-list="diamond"] { list-style-type: "◆   "; }
.tw-jianya.resume-paper .paper-rich ul[data-list="diamond-open"] { list-style-type: "◇   "; }
.tw-jianya.resume-paper .paper-rich ul[data-list="diamond"] > li::marker,
.tw-jianya.resume-paper .paper-rich ul[data-list="diamond-open"] > li::marker { font-size: 0.62em; }
.tw-jianya.resume-paper .paper-rich ul[data-list="triangle"] { list-style-type: "▸   "; }
.tw-jianya.resume-paper .paper-rich ul[data-list="check"] { list-style-type: "✓   "; }
.tw-jianya.resume-paper .paper-rich ul[data-list="check"] > li::marker { font-size: 0.75em; }
.tw-jianya.resume-paper .paper-rich ol[data-list="decimal"] { list-style-type: decimal; }
.tw-jianya.resume-paper .paper-rich ol[data-list="cjk"] { list-style-type: miniwho-cjk; }
.tw-jianya.resume-paper .paper-rich ol[data-list="roman-upper"] { list-style-type: upper-roman; }
.tw-jianya.resume-paper .paper-rich ol[data-list="roman-lower"] { list-style-type: lower-roman; }
.tw-jianya.resume-paper .paper-rich ol[data-list="alpha-upper"] { list-style-type: upper-alpha; }
.tw-jianya.resume-paper .paper-rich ol[data-list="alpha-lower"] { list-style-type: lower-alpha; }
.tw-jianya.resume-paper .paper-rich ol[data-list="paren"] { padding-left: 1.2em; list-style: none; counter-reset: paren-item; }
.tw-jianya.resume-paper .paper-rich ol[data-list="paren"] > li { position: relative; counter-increment: paren-item; }
.tw-jianya.resume-paper .paper-rich ol[data-list="paren"] > li::before {
  content: "（" counter(paren-item) "）";
  position: absolute;
  right: calc(100% + 0.08em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  font-size: 0.62em;
  line-height: 1.7;
  white-space: nowrap;
}
.tw-jianya.resume-paper .paper-rich ol[data-list="paren-right"] { padding-left: 1.2em; list-style: none; counter-reset: paren-right-item; }
.tw-jianya.resume-paper .paper-rich ol[data-list="paren-right"] > li { position: relative; counter-increment: paren-right-item; }
.tw-jianya.resume-paper .paper-rich ol[data-list="paren-right"] > li::before {
  content: counter(paren-right-item) ")";
  position: absolute;
  right: calc(100% + 0.12em);
  top: 0;
  font-family: var(--mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* 日期左栏：base 版式给的 17mm 装不下「2023.09 — 2026.06」，会折成两行。
   加宽到 35mm 并禁止换行，日期始终单行、上下对齐。 */
.tw-jianya.layout-center.resume-paper .paper-item {
  grid-template-columns: 35mm minmax(0, 1fr);
  align-items: baseline;
}

.tw-jianya.layout-center.resume-paper .paper-item-period {
  white-space: nowrap;
}

/* 没有日期的条目（作品集、技能等）不该再占着空的日期列，否则整体右移 */
.tw-jianya.resume-paper .paper-item.paper-item--undated {
  grid-template-columns: 0 minmax(0, 1fr);
  column-gap: 0;
}
/* 工作地点上移到标题行：日期 — 单位 — 地点 一行读齐，地点贴最右；副行只留岗位 / 部门 / 性质。 */
.tw-jianya.layout-center.resume-paper .is-work_experience .paper-item {
  grid-template-columns: 35mm minmax(0, 1fr) auto;}
.tw-jianya.layout-center.resume-paper .is-work_experience .paper-item-city {
  display: inline;
  grid-column: 3;
  grid-row: 1;
  justify-self: end;
  color: #7c898d;
  font-size: calc(var(--paper-base-size) * 0.78);
  white-space: nowrap;}
.tw-jianya.layout-center.resume-paper .is-work_experience .paper-item-sub__city {
  display: none;}
